'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var factorial = require( '@stdlib/math/base/special/factorial' );
var incrspace = require( '@stdlib/array/base/incrspace' );
var ldexp = require( '@stdlib/math/base/special/ldexp' );
var zeta = require( '@stdlib/math/base/special/riemann-zeta' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var polygamma = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( polygamma instanceof Error )
};


// FIXTURES //

var largePositive = require( './fixtures/cpp/large_positive.json' );
var largeNegative = require( './fixtures/cpp/large_negative.json' );
var smallPositive = require( './fixtures/cpp/small_positive.json' );
var hugePositive = require( './fixtures/cpp/huge_positive.json' );
var positive = require( './fixtures/cpp/positive.json' );
var negative = require( './fixtures/cpp/negative.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof polygamma, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for `x`, the function returns `NaN`', opts, function test( t ) {
	var val = polygamma( 1, NaN );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	val = polygamma( 2, NaN );
	t.strictEqual( isnan( val ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a negative `n`, the function returns `NaN`', opts, function test( t ) {
	var val = polygamma( -1, 5.3 );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	val = polygamma( -3, 2.5 );
	t.strictEqual( isnan( val ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided an even negative integer for `x`, the function returns `NaN`', opts, function test( t ) {
	var val = polygamma( 2, -2.0 );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	val = polygamma( 2, -4.0 );
	t.strictEqual( isnan( val ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided an odd negative integer for `x`, the function returns positive infinity', opts, function test( t ) {
	var val = polygamma( 4, -1.0 );
	t.strictEqual( val, PINF, 'returns expected value' );

	val = polygamma( 4, -3.0 );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the polygamma function for small positive numbers', opts, function test( t ) {
	var expected;
	var n;
	var x;
	var y;
	var i;

	n = smallPositive.n;
	x = smallPositive.x;
	expected = smallPositive.y;
	for ( i = 0; i < x.length; i++ ) {
		y = polygamma( n[ i ], x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 4 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the polygamma function for positive numbers', opts, function test( t ) {
	var expected;
	var n;
	var x;
	var y;
	var i;

	n = positive.n;
	x = positive.x;
	expected = positive.y;
	for ( i = 0; i < x.length; i++ ) {
		y = polygamma( n[ i ], x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 16 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the polygamma function for negative numbers', opts, function test( t ) {
	var expected;
	var n;
	var x;
	var y;
	var i;

	n = negative.n;
	x = negative.x;
	expected = negative.y;
	for ( i = 0; i < x.length; i++ ) {
		y = polygamma( n[ i ], x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 2900 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the polygamma function for large positive numbers', opts, function test( t ) {
	var expected;
	var n;
	var x;
	var y;
	var i;

	n = largePositive.n;
	x = largePositive.x;
	expected = largePositive.y;
	for ( i = 0; i < x.length; i++ ) {
		y = polygamma( n[ i ], x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 20 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the polygamma function for large negative numbers', opts, function test( t ) {
	var expected;
	var n;
	var x;
	var y;
	var i;

	n = largeNegative.n;
	x = largeNegative.x;
	expected = largeNegative.y;
	for ( i = 0; i < x.length; i++ ) {
		y = polygamma( n[ i ], x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 2800 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the polygamma function for huge positive numbers', opts, function test( t ) {
	var expected;
	var n;
	var x;
	var y;
	var i;

	n = hugePositive.n;
	x = hugePositive.x;
	expected = hugePositive.y;
	for ( i = 0; i < x.length; i++ ) {
		y = polygamma( n[ i ], x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'for positive odd `n` and `x` equal to `1.0`, the function computes the factorial of `n` multiplied by the Riemann zeta function evaluated at `n+1`', opts, function test( t ) {
	var expected;
	var actual;
	var values;
	var i;
	var n;

	values = incrspace( 1, 99, 2 );
	for ( i = 0; i < values.length; i++ ) {
		n = values[ i ];
		expected = factorial( n ) * zeta( n+1 );
		actual = polygamma( n, 1.0 );
		t.strictEqual( isAlmostSameValue( actual, expected, 0 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'for positive even `n` and `x` equal to `1.0`, the function computes the negative factorial of `n` multiplied by the Riemann zeta function evaluated at `n+1`', opts, function test( t ) {
	var expected;
	var actual;
	var values;
	var i;
	var n;

	values = incrspace( 2, 100, 2 );
	for ( i = 0; i < values.length; i++ ) {
		n = values[ i ];
		expected = (-1.0) * factorial( n ) * zeta( n+1 );
		actual = polygamma( n, 1.0 );
		t.strictEqual( isAlmostSameValue( actual, expected, 0 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'for positive odd `n` and `x` equal to `0.5`, the function computes the factorial of `n` multiplied by the Riemann zeta function evaluated at `n+1`', opts, function test( t ) {
	var expected;
	var actual;
	var values;
	var i;
	var n;

	values = incrspace( 1, 199, 2 );
	for ( i = 0; i < values.length; i++ ) {
		n = values[ i ];
		expected = factorial( n ) * zeta( n+1 );
		expected *= ldexp( 1.0, n + 1 ) - 1.0;
		actual = polygamma( n, 0.5 );
		t.strictEqual( isAlmostSameValue( actual, expected, 0 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'for positive even `n` and `x` equal to `0.5`, the function computes the negative factorial of `n` multiplied by the Riemann zeta function evaluated at `n+1`', opts, function test( t ) {
	var expected;
	var actual;
	var values;
	var i;
	var n;

	values = incrspace( 2, 200, 2 );
	for ( i = 0; i < values.length; i++ ) {
		n = values[ i ];
		expected = (-1.0) * factorial( n ) * zeta( n+1 );
		expected *= ldexp( 1.0, n + 1 ) - 1.0;
		actual = polygamma( n, 0.5 );
		t.strictEqual( isAlmostSameValue( actual, expected, 0 ), true, 'returns expected value' );
	}
	t.end();
});
